using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;
using Microsoft.EntityFrameworkCore.ChangeTracking;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: discriminator property renamed
            // from "Discriminator" to "$type". Preserve the old name so the
            // 500K existing documents stay readable and direct SQL queries
            // that reference c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: id synthesis changed from
            // "EntityType|Key" to just the raw key. Map an explicit CosmosId
            // property to the JSON "id" field using the legacy format so
            // existing documents with ids like "Product|123" are found.
            entity.Property(p => p.CosmosId)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
            entity.HasPartitionKey(p => p.Id);

            // EF Core 9 breaking change #3: HasIndex() now throws for
            // Cosmos (it was silently ignored before). Removed.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        base.OnConfiguring(options);
    }
}

/// <summary>
/// Reproduces the EF Core 8 "EntityType|Key" id format for backward compat.
/// </summary>
